<script setup>
import { computed, inject, nextTick, ref, watch } from 'vue';
import { consoleKey } from '../composables/useConsole';
const c = inject(consoleKey), following = ref(true), reasoningBox = ref(null), answerBox = ref(null);
const stages = { queued:'排队中', preparing:'准备输入', searching:'联网检索', thinking:'正在思考', answering:'正在回答', drafting:'撰写文档', rendering:'排版导出', sending:'发送到 QQ', generated:'生成完成', sent:'已发送', skipped:'保持安静', failed:'调用失败', send_failed:'发送失败', cancelled:'已取消' };
const tasks = computed(() => c.state.liveTasks?.tasks || []);
const selected = computed(() => c.state.liveTasks?.selected?.id === c.state.liveSelectedId ? c.state.liveTasks.selected : null);
const active = computed(() => tasks.value.filter(task => !task.endedAt).length);
const channel = task => task.messageType === 'private' ? `私聊 · QQ ${task.user}` : task.group ? `群 ${task.group}${task.user ? ' · QQ ' + task.user : ''}` : task.source === 'scheduled_chat' ? '定时问候' : '后台模型请求';
watch(() => [selected.value?.reasoning, selected.value?.answer], async () => { if (following.value) { await nextTick(); for (const box of [reasoningBox.value, answerBox.value]) if (box) box.scrollTop = box.scrollHeight; } });
</script>
<template>
  <section class="page" id="page-live">
    <div class="page-heading"><div><span class="eyebrow">LIVE WORKSPACE</span><h1>看见对话的进行时<span class="title-dot">.</span></h1><p class="muted">问题、模型实际返回的思考与答案，每秒更新。</p></div><button class="secondary" :disabled="c.state.busy.live" @click="c.loadLiveTasks">刷新任务</button></div>
    <div class="live-banner"><span><i aria-hidden="true" />{{ active ? `${active} 个任务处理中` : '等待下一次对话' }}</span><small>仅限已登录的管理后台 · 最近 30 项 · 服务重启后清空</small></div>
    <p v-if="c.state.liveError" class="live-error" role="status">{{ c.state.liveError }}，正在重试；下方可能是上次状态。</p>
    <div class="live-layout">
      <aside class="card task-list" aria-label="模型任务列表"><div class="panel-heading"><h2>问题队列</h2><span class="subtle-tag">{{ tasks.length }}</span></div><p v-if="!tasks.length" class="empty">暂无任务<br><small>在授权群 @ 或通过白名单私聊提问后，这里会显示进度。</small></p><button v-for="task in tasks" :key="task.id" type="button" class="task-row" :aria-pressed="c.state.liveSelectedId === task.id" @click="c.selectLiveTask(task.id)"><span class="task-stage" :class="{ active:!task.endedAt }">{{ stages[task.stage] || task.stage }}</span><b>{{ task.question || '图片或后台任务' }}</b><small>{{ channel(task) }}</small><time>{{ new Date(task.startedAt).toLocaleTimeString('zh-CN',{hour12:false}) }}</time></button></aside>
      <article class="card task-detail">
        <template v-if="selected"><div class="task-heading"><div><span class="eyebrow">{{ selected.modelProfileName ? selected.modelProfileName + ' · ' : '' }}{{ selected.model || '正在确认模型' }}</span><h2>{{ stages[selected.stage] || selected.stage }}</h2><p>{{ channel(selected) }}<template v-if="selected.userName"> · {{ selected.userName }}</template></p></div><label class="follow-toggle"><input v-model="following" type="checkbox">跟随输出</label></div>
          <section class="live-section"><h3>当前问题</h3><pre class="question-text">{{ selected.question || '暂无文字问题' }}</pre></section>
          <section class="live-section"><h3>模型返回的思考<span>{{ selected.streaming === false ? '接口返回完整结果后显示' : '仅展示接口实际返回的内容' }}</span></h3><pre v-if="selected.reasoning" ref="reasoningBox" class="stream-text thinking-text">{{ selected.reasoning }}</pre><p v-else class="stream-placeholder">{{ selected.endedAt ? '接口未返回可展示的思考内容。' : '等待模型返回思考内容；未开启思考或接口不提供时不会显示。' }}</p><p v-if="selected.reasoningTruncated" class="live-note">思考展示已达 30,000 字符，仅保留前段。</p></section>
          <section class="live-section"><h3>回答内容<span>{{ selected.endedAt ? '本次任务结果' : '生成中的预览，尚不代表 QQ 已发送' }}</span></h3><pre v-if="selected.answer" ref="answerBox" class="stream-text">{{ selected.answer }}</pre><p v-else class="stream-placeholder">{{ selected.endedAt ? '本次没有可显示的回答正文。' : '等待回答正文…' }}</p><p v-if="selected.answerTruncated" class="live-note">回答展示已达 20,000 字符。</p></section>
          <p class="live-note">最近更新 {{ new Date(selected.updatedAt).toLocaleTimeString('zh-CN',{hour12:false}) }}<template v-if="selected.tokens != null"> · {{ selected.tokens }} Tokens</template>。思考不发到 QQ、不写入聊天数据库或普通日志；只在本次进程的实时面板中临时保留。</p>
        </template><p v-else class="detail-empty">{{ c.state.busy.live ? '正在读取任务…' : '选择一条任务，查看当前问题和实时输出。' }}</p>
      </article>
    </div>
  </section>
</template>
<style scoped>
