argin-top:22px; }.live-section h3 { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; font-size:13px; font-weight:550; margin:0 0 12px; }.live-section h3 span { font-size:10px; color:var(--muted); font-weight:400; }.question-text,.stream-text { white-space:pre-wrap; overflow-wrap:anywhere; word-break:break-word; font:inherit; font-size:13px; line-height:1.9; padding:16px; margin:0; background:#f6f8ff; border:1px solid var(--line); border-radius:10px; max-height:420px; overflow:auto; }.question-text { max-height:200px; }.thinking-text { background:#eef2fc; color:#52688b; }.stream-placeholder { border:1px dashed var(--line); border-radius:10px; padding:18px; color:var(--muted); font-size:12px; }.task-detail > .live-note { margin:22px 0 0; }.detail-empty { text-align:center; color:var(--muted); padding:80px 20px; font-size:13px; }.live-error { color:var(--red); font-size:12px; }
@media(max-width:850px) { .live-layout { grid-template-columns:1fr; }.task-list { max-height:300px; }.live-banner { flex-wrap:wrap; }.task-detail { padding:20px; } }@media(max-width:650px) { .live-section h3 span { font-size:11px; }.task-row small,.task-row time { font-size:11px; }.task-heading { flex-wrap:wrap; }.stream-text { font-size:14px; }.live-banner { gap:8px; } }
</style>
